3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	
7	/**
8	 * Derives the stable household identifier shared by owners at the same household,
9	 * i.e. having the same last name and address (compared case-insensitively with
10	 * collapsed whitespace). The value is a pure function of those two fields, so every
11	 * owner in one household resolves to the same id without any stored state.
12	 */
13	public final class HouseholdId {
14	
15	    private HouseholdId() {
16	    }
17	
18	    public static String of(String lastName, String address) {
19	        String key = normalize(lastName) + "|" + normalize(address);
20	        try {
21	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
22	            StringBuilder sb = new StringBuilder("H-");
23	            for (int i = 0; i < 6; i++) {
24	                sb.append(String.format("%02x", digest[i]));
25	            }
26	            return sb.toString();
27	        } catch (NoSuchAlgorithmException e) {
28	            throw new IllegalStateException(e);
29	        }
30	    }
31	
32	    private static String normalize(String value) {
33	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
34	    }
35	}
